export function TimePicker({
  label = "{{label}}",
  format = "{{format}}",
  value = "{{value}}",
  accent = "{{accent}}",
  required = {{required}},
}) {
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", maxWidth: 220 }}>
      <label style={{ display: "block", marginBottom: 6, fontWeight: 500 }}>{label}{required && " *"}</label>
      <details>
        <summary style={{
          display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, listStyle: "none",
          cursor: "pointer", padding: "10px 12px", border: `1.5px solid ${accent}`, borderRadius: 8, background: "#FAF7F2",
        }}>
          <span>{value}</span>
          <span style={{ fontSize: 11, color: "#24143080", textTransform: "uppercase" }}>{format}</span>
        </summary>
        <ul style={{ listStyle: "none", margin: "8px 0 0", padding: 4, border: "1.5px solid #24143020", borderRadius: 8, maxHeight: 140, overflowY: "auto" }}>
          {["1:00 PM", "1:30 PM", "2:30 PM", "3:00 PM", "3:30 PM"].map((t) => (
            <li key={t} style={{
              padding: "6px 8px", borderRadius: 6, fontSize: 13,
              background: t === "2:30 PM" ? accent : undefined,
              fontWeight: t === "2:30 PM" ? 600 : undefined,
            }}>{t}</li>
          ))}
        </ul>
      </details>
    </div>
  );
}
